 const [shouldAutoConnect,setShouldAutoConnect]=useState(false);const autoConnectAttempts=useRef(0);const promptedForConnection=useRef(false);const [clearingArtwork,setClearingArtwork]=useState(false);const [pickerCategory,setPickerCategory]=useState<'Arcade'|'Consoles'|'Computers'>('Arcade');
 const [sort,setSort]=useState<SortOrder>('collection');const [savedOnly,setSavedOnly]=useState(false);
 const [saved,setSaved]=useState<string[]>([]);const [playHistory,setPlayHistory]=useState<Record<string,number>>({});const [nowPlayingId,setNowPlayingId]=useState<string|null>(null);const [ready,setReady]=useState(false);const [batchSystems,setBatchSystems]=useState<string[]>([]);const [batchMenu,setBatchMenu]=useState(false);const [batchRunning,setBatchRunning]=useState(false);const [batchProgress,setBatchProgress]=useState({done:0,total:0});const [maintenanceSystems,setMaintenanceSystems]=useState<MiSTerSystem[]>([]);const [maintenanceSelection,setMaintenanceSelection]=useState<string[]>([]);const [maintenanceMenu,setMaintenanceMenu]=useState(false);const [maintenanceRunning,setMaintenanceRunning]=useState(false);const [maintenanceProgress,setMaintenanceProgress]=useState<LibraryMaintenanceProgress|null>(null);
 const [selected,setSelected]=useState<Game|null>(null);const [cardDirection,setCardDirection]=useState<'previous'|'next'|null>(null);const [panel,setPanel]=useState<'sort'|'device'|'system'|'genre'|'new-playlist'|'edit-playlist'|'playlist-add'|'delete-playlist'|null>(null);
 const [tab,setTab]=useState<'library'|'playlists'|'discover'>('library');const [playlists,setPlaylists]=useState<Playlist[]>([]);const [activePlaylistId,setActivePlaylistId]=useState<string|null>(null);const [playlistName,setPlaylistName]=useState('');const [playlistQuery,setPlaylistQuery]=useState('');const [playlistGameId,setPlaylistGameId]=useState<string|null>(null);const [discoverySeedId,setDiscoverySeedId]=useState<string|null>(null);const [discoveryRecommendations,setDiscoveryRecommendations]=useState<ReturnType<typeof recommendGames>>([]);const [discoveryLoading,setDiscoveryLoading]=useState(false);
