 async function batchLibretro(){if(!batchSystems.length||batchRunning)return;setBatchRunning(true);const total=libraryGames.filter(game=>batchSystems.includes(game.system)).length;setBatchProgress({done:0,total});try{const result=await batchDownloadLibretro(libraryGames,batchSystems,(done,totalItems)=>setBatchProgress({done,total:totalItems}));const stats=await getLibretroArtworkStats();setArtworkCacheStats(stats);notify(result.checked?`${result.available.toLocaleString()} of ${result.checked.toLocaleString()} games have cached artwork. ${result.unmatched.toLocaleString()} had no Libretro match.`:'No games matched the selected system.');}finally{setBatchRunning(false);}}
 async function clearArtworkCache(){if(clearingArtwork||batchRunning)return;setClearingArtwork(true);try{await clearLibretroArtworkCache();setArtworkCacheStats({count:0,bytes:0});notify('Downloaded artwork cleared from this device.');}catch{notify('Could not clear downloaded artwork. Please try again.');}finally{setClearingArtwork(false);}}
