 async function refreshLibraryAndMetadata(){if(maintenanceRunning)return;try{const url=normaliseMiSTerUrl(misterUrl);setMaintenanceRunning(true);setMaintenanceMenu(false);setMaintenanceProgress({stage:'indexing',message:'Preparing your MiSTer refresh…'});const found=await refreshMiSTerLibraryAndMetadata(url,maintenanceSelection,setMaintenanceProgress);if(!found.length)throw new Error('Zaparoo finished, but did not return any games.');setLibraryRecords(found);setConnected(true);await saveCachedMiSTerLibrary(found);notify(`${found.length.toLocaleString()} games refreshed with MiSTer metadata.`);}catch(error){notify(error instanceof Error?error.message:'Could not refresh the library.');}finally{setMaintenanceRunning(false);setMaintenanceProgress(null);}}
