function LibraryReadProgress({count}:{count:number}){const travel=useRef(new Animated.Value(0)).current;useEffect(()=>{const animation=Animated.loop(Animated.timing(travel,{toValue:1,duration:1200,useNativeDriver:true}));animation.start();return()=>animation.stop();},[travel]);return <View style={s.readProgress}><View style={s.readProgressTrack}><Animated.View style={[s.readProgressFill,{transform:[{translateX:travel.interpolate({inputRange:[0,1],outputRange:['-120%','260%']})}]}]}/></View><Text style={s.readProgressText}>{count?`${count.toLocaleString()} games read`:'Opening your library…'}</Text></View>;}
